    ["Opens: Unit Auras > Aura Filters & Sorting"] = "Si apre: Aure unità > Filtri e ordinamento delle aure",
    ["Opens: Unit Auras > Caps & Icons"] = "Si apre: Aure unità > Cappellini e icone",
    ["Opens: Unit Auras > Display"] = "Si apre: Aure dell'unità > Visualizza",
    ["Opens: Unit Auras > Player > Custom caps > Caps & Icons > Max Buffs"] = "Si apre: Aure unità > Giocatore > Cappellini personalizzati > Cappellini e icone > Buff massimi",
    ["Opens: Unit Auras > Text Coloring"] = "Si apre: Aure dell'unità > Colorazione del testo",
    ["Padding"] = "Imbottitura",
    ["Party, Raid, and Mythic Raid Group Frame layout, bars, auras, indicators, scope overrides and positions"] = "Layout del gruppo Party, Raid e Raid Mitico, barre, aure, indicatori, impostazioni di mirino e posizioni",
    ["Position"] = "Posizione",
    ["Positions class bar ABOVE Essential Cooldowns"] = "Posiziona la barra della classe SOPRA i tempi di recupero essenziali",
    ["Preserve HP color on all unit frames"] = "Conserva il colore HP su tutti i telai delle unità",
    ["Press Ctrl+C to copy:"] = "Premere Ctrl+C per copiare:",
    ["Preview follows the current castbar visibility, icon, text, and global color settings."] = "L'anteprima segue le impostazioni attuali di visibilità, icona, testo e colore globale della barra di cast.",
    ["Profile actions"] = "Azioni del profilo",
    ["Quick Setup: Detached Class Bar"] = "Configurazione rapida: barra della classe separata",
    ["Reload"] = "Ricarica",
    ["Rows"] = "Righe",
    ["Same setting as each unit page > Transparency. It uses this same HP track color; off here means at least one unit frame is off."] = "Stessa impostazione di ciascuna pagina dell'unità > Trasparenza. Utilizza lo stesso colore della traccia HP; spento qui significa che almeno un telaio dell'unità è spento.",
    ["Secret aura (name/fingerprint matched)"] = "Aura segreta (nome/fingerprint corrispondente)",
    ["Select:"] = "Seleziona:",
    ["Set Bar Background Tint to white and enable Custom color in Dark Mode. If black, enable Preserve HP color on all unit frames."] = "Imposta la tinta dello sfondo della barra su bianco e attiva il colore personalizzato in modalità scura. Se nero, abilitare Preserva colore HP su tutti i telai delle unità.",
    ["Setup Now"] = "Configura ora",
    ["Slot"] = "Scanalatura",
    ["Some layout changes rebuild frames, while visual changes apply instantly. If needed, close and reopen the menu or reload after large profile/import changes."] = "Alcune modifiche al layout ricostruiscono i riquadri, mentre le modifiche visive vengono applicate immediatamente. Se necessario, chiudi e riapri il menu o ricaricalo dopo modifiche importanti al profilo/import.",
    ["Syncs & anchors power bar to class resources"] = "Sincronizza e ancora la barra di alimentazione alle risorse della classe",
    ["The active profile is saved per character. New characters start on this profile instead of Default."] = "Il profilo attivo viene salvato per personaggio. I nuovi personaggi iniziano con questo profilo invece di Default.",
    ["This layer is off in settings and cannot be shown in preview."] = "Questo livello è disattivato nelle impostazioni e non può essere mostrato in anteprima.",
    ["Type a name here before creating or copying a profile."] = "Digitare qui un nome prima di creare o copiare un profilo.",
    ["Undo"] = "Annulla",
    ["Unit Frame Preview"] = "Anteprima del riquadro dell'unità",
    ["Unit frame status icons are on each unit page. Group frame indicators are in Group Frames > Indicators."] = "Le icone di stato del frame dell'unità si trovano su ciascuna pagina dell'unità. Gli indicatori dei frame di gruppo si trovano in Frame di gruppo > Indicatori.",
    ["Use /msuf to open MSUF2. The Dashboard also contains reset, support, profile, and scale tools."] = "Usa /msuf per aprire MSUF2. La dashboard contiene anche strumenti di ripristino, supporto, profilo e ridimensionamento.",
    ["Use Dashboard > Reset Positions for frame movers. Use Profiles only when you want to reset, copy, import, or replace profile data."] = "Utilizza Dashboard > Ripristina posizioni per i spostatori di frame. Utilizza i Profili solo quando desideri reimpostare, copiare, importare o sostituire i dati del profilo.",
    ["Use Global Style > Bars for highlight borders and Group Frames > Indicators for role, threat, dispel, spell, corner, and raid-marker indicators."] = "Utilizza Stile globale > Barre per evidenziare i bordi e Riquadri di gruppo > Indicatori per indicatori di ruolo, minaccia, dissolvenza, incantesimo, angolo e indicatore di incursione.",
    ["Use Group Frames > Layout for size and spacing, Buffs & Debuffs for aura clutter, and Indicators for fixed-position status icons."] = "Usa Riquadri di gruppo > Layout per dimensioni e spaziatura, Buff e Debuff per il disordine dell'aura e Indicatori per le icone di stato a posizione fissa.",
    ["Use Group Frames pages: Layout for size/growth/sorting, Health & Text for bars/text, Buffs & Debuffs for auras, and Indicators for status icons."] = "Utilizza le pagine dei frame di gruppo: layout per dimensione/growth/sorting, salute e testo per le barre/text, buff e debuff per le aure e indicatori per le icone di stato.",
    ["Use MSUF Edit Mode to drag a single unit frame. Use the unit page > Anchoring when you need exact anchor targets or X/Y values."] = "Utilizzare la modalità di modifica MSUF per trascinare un riquadro a unità singola. Utilizza la pagina dell'unità > Ancoraggio quando hai bisogno di target di ancoraggio esatti o valori X/Y.",
    ["Use MSUF Edit Mode to drag supported castbars. Per-unit castbar enable/icon/text options are on each unit page; shared castbar style is in Global Style > Castbar."] = "Utilizza la modalità di modifica MSUF per trascinare le barre di cast supportate. Le opzioni di abilitazione castbar per unità/icon/text si trovano nella pagina di ciascuna unità; lo stile castbar condiviso si trova in Stile globale > Castbar.",
    ["Use MSUF Edit Mode to drag the player frame. For exact anchor or X/Y values, open Player > Anchoring after that."] = "Utilizzare la modalità di modifica MSUF per trascinare il riquadro del lettore. Per l'ancoraggio esatto o i valori X/Y, apri quindi Giocatore > Ancoraggio.",
    ["Use the Dashboard scale controls for menu scale or UI scale. You can also resize the MSUF2 window from its corner."] = "Utilizza i controlli della scala del dashboard per la scala del menu o la scala UI. Puoi anche ridimensionare la finestra MSUF2 dal suo angolo.",
    ["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, GCD, text, and interrupt options."] = "Utilizza la pagina delle unità per attivare/disattivare la barra di cast per unità e Stile globale > Barra di cast per opzioni di texture condivise, direzione, GCD, testo e interruzione.",
    ["Use this if HP Bar fade makes the empty health area disappear or look black. It keeps the same HP track color from Colors."] = "Usalo se la dissolvenza della barra HP fa scomparire l'area della salute vuota o farla sembrare nera. Mantiene lo stesso colore della traccia HP di Colors.",
    ["Value:"] = "Valore:",
    ["View"] = "Visualizza",
    ["Welcome to Class Resources!"] = "Benvenuto in Risorse per la classe!",
    ["WoW blocks some protected frame changes in combat. Leave combat, then apply layout, anchoring, enable/disable, profile, or protected-frame changes."] = "WoW blocca alcune modifiche al frame protetto in combattimento. Abbandona il combattimento, quindi applica modifiche al layout, all'ancoraggio, all'abilitazione/disable, al profilo o al frame protetto.",
    ["bottom"] = "fondo",
    ["change background color unit frames"] = "cambiare colore di sfondo dei riquadri unità",
    ["class-resource layout, behavior, style, auto-hide, detached power bar and alternative mana settings"] = "layout delle risorse di classe, comportamento, stile, nascondimento automatico, barra di potenza staccata e impostazioni di mana alternative",
    ["click layers to hide - drag preview elements - arrows nudge selected"] = "fare clic sui livelli da nascondere - trascinare gli elementi di anteprima - le frecce spostano la selezione",
    ["frame colors, class/NPC colors, power colors, castbar colors, aura colors and gameplay color settings"] = "colori della cornice, colori della classe/NPC, colori del potere, colori della barra di cast, colori dell'aura e impostazioni dei colori di gioco",
    ["gameplay enhancement settings such as combat text, crosshair and click-cast behavior"] = "impostazioni di miglioramento del gameplay come testo di combattimento, mirino e comportamento del clic-cast",
    ["gf_layout"] = "gf_layout",
    ["global castbar behavior, textures, GCD, boss castbar and interrupt indicator settings"] = "comportamento globale della barra di cast, texture, GCD, barra di cast del boss e impostazioni dell'indicatore di interruzione",
    ["language/menu behavior, update pacing, tooltips, Blizzard-frame handling, minimap icon, sounds and range-fade settings"] = "comportamento della lingua/menu, ritmo degli aggiornamenti, descrizioni comandi, gestione dei riquadri Blizzard, icona della minimappa, suoni e impostazioni di dissolvenza della gamma",
    ["none"] = "nessuno",
    ["optional style/module settings such as MSUF Style and dropdown style"] = "impostazioni style/module opzionali come stile MSUF e stile a discesa",
    ["scope disabled"] = "ambito disabilitato",
    ["shared"] = "condiviso",
    ["shared bar textures, gradients, rounded frame corners, absorb display, outlines, highlight borders, power smoothing and all per-unit/group bar overrides"] = "texture delle barre condivise, gradienti, angoli arrotondati delle cornici, visualizzazione assorbita, contorni, bordi evidenziati, livellamento potente e tutte le sostituzioni della barra per unità/group",
    ["shared font family, text style, name/power text coloring, name shortening and all per-unit/group font overrides"] = "famiglia di caratteri condivisa, stile del testo, colorazione del testo name/power, abbreviazione del nome e tutte le sostituzioni dei caratteri per unità/group",
    ["the entire active profile"] = "l'intero profilo attivo",
    ["uf_target"] = "uf_target",
    ["–"] = "–",
}
for k, v in pairs(MSUF_LOCALE_COVERAGE_itIT) do
