L["|cffffd700MSUF:|r Group Frames reset to defaults."] = "|cffffd700MSUF:|r Frame di gruppo ripristinati ai valori predefiniti."
L["|cffffd700MSUF:|r Preserve HP color uses the same HP track color from Colors, but some bar textures may look different."] = "|cffffd700MSUF:|r Mantieni colore HP usa lo stesso colore traccia HP da Colori, ma alcune texture barra possono apparire diverse."
L["Click a handle to select - drag custom layers - arrow keys nudge selected; Blizzard is locked"] = "Fai clic su una maniglia per selezionare - trascina i livelli personalizzati - le frecce spostano la selezione; Blizzard è bloccato"
L["Copy categories"] = "Categorie da copiare"
L["Copy Selected"] = "Copia selezionati"
L["Custom Anchor Frame"] = "Frame ancora personalizzato"
L["Custom anchor target (mouse picker)"] = "Bersaglio ancora personalizzato (selettore mouse)"
L["Don't show again"] = "Non mostrare più"
L["Frame disabled"] = "Frame disabilitato"
L["Growth Direction"] = "Direzione di crescita"
L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "Mantieni colore HP conserva il colore di riempimento HP mentre la dissolvenza livello è attiva e disegna la salute mancante separatamente con lo stesso colore traccia HP da Colori.\n\nPuò aiutare quando la dissolvenza della barra HP fa sparire l'area vuota o la fa sembrare nera. Alcune texture personalizzate possono comunque apparire piatte, scure o diverse con questa opzione attiva."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Ripristinare %s ai valori predefiniti?\n\nQuesto ripristina %s per il profilo attivo. I valori predefiniti vengono letti dal profilo di fabbrica MSUF attuale, quindi le future modifiche predefinite saranno usate automaticamente."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "Ripristinare %s ai valori predefiniti?\n\nQuesto ripristina l'intero profilo attivo '%s' ai valori di fabbrica MSUF attuali. Tutti i menu di quel profilo saranno interessati."
L["Reset Scopes"] = "Ripristina ambiti"

