L["|cffff6060CTRL required:|r |cffffffffhold |r|cff55ff55CTRL + Left-Click|r|cffffffff to confirm the anchor target.|r"] = "|cffff6060CTRL richiesto:|r |cfffffffftieni premuto |r|cff55ff55CTRL + clic sinistro|r|cffffffff per confermare il bersaglio di ancoraggio.|r"
