L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Aggiunto supporto al riquadro Bersaglio della focalizzazione in impostazioni unità, modalità modifica, anteprime, destinazioni copia, opzioni testo, icone e refresh runtime."
L["Added improved on/off switch visuals."] = "Aggiunti visual migliorati per switch on/off."
