L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Aggiunto layout card Menu2 ridisegnato per pagine unità, gruppo, aura, indicatori, barre e avanzate."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Aggiunti riquadri arrotondati con controlli per superficie per unità, gruppi, barre, evidenziazioni, overlay, assorbimenti e indicatori."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "Aggiunti media maschera arrotondata per riquadri live e anteprima Menu2."
