L["Blizzard controls this aura block, so MSUF cannot drag it. Switch to MSUF Custom mode if you want full positioning control. The preview marks the Blizzard-owned area."] = "Blizzard controlla questo blocco aure, quindi MSUF non può trascinarlo. Passa a MSUF personalizzato per il controllo completo della posizione. L'anteprima indica l'area gestita da Blizzard."
L["Blizzard locked"] = "Bloccato da Blizzard"
L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "La modalità Blizzard lascia a WoW il posizionamento dei tipi di aura selezionati. La modalità MSUF personalizzata consente a MSUF di controllare dimensione, crescita, posizione, filtri e stile. Bagliore dispel non è disponibile solo negli ambiti dei riquadri gruppo in cui Blizzard controlla il livello aure."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "Blizzard mostra il testo di recupero e accumuli per buff e debuff nativi. Questi campi di testo influenzano solo le icone personalizzate."
