L["Reset all Group Frame settings to defaults?\n\nThis resets Party, Raid, and Mythic Raid Group Frames for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "Ripristinare tutte le impostazioni dei riquadri gruppo?\n\nQuesto ripristina Party, Raid e Raid Mitico per il profilo attivo. I predefiniti sono letti dal profilo factory attuale di MSUF, quindi le modifiche future ai predefiniti verranno usate automaticamente."
