L["This group scope follows Shared name shortening. Turn on custom settings above only when group names need different truncation."] = "Questo ambito gruppo segue l'abbreviazione nomi condivisa. Attiva impostazioni personalizzate sopra solo se i nomi gruppo richiedono un troncamento diverso."
