L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "La modalità Blizzard lascia a WoW il posizionamento dei tipi di aura selezionati. La modalità MSUF personalizzata consente a MSUF di controllare dimensione, crescita, posizione, filtri e stile. Le evidenziazioni dispel MSUF mantengono le icone Blizzard e permettono a MSUF di mostrare bordo, bagliore e overlay dispel."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Il renderer Blizzard e ancora attivo, ma questo gruppo e MSUF Custom perche il suo interruttore Usa Blizzard e disattivato. Altri tipi di aura Blizzard attivi possono ancora mostrare incantesimi corrispondenti, quindi possono apparire duplicati."
