L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "Apri Riquadri gruppo > Salute e testo. Controlla colori salute, barre, barra risorsa, testo, overlay dispel, striscia debuff e dissolvenza per portata. La previsione cure è in Stile globale > Barre > Visualizzazione assorbimenti."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "Apri Aure unità > Elenco globale ignorati. Può nascondere categorie di aure predefinite per tutti i riquadri unità, oppure per singola unità dopo aver abilitato Sovrascrivi per questa unità. MSUF al momento non ha una blacklist libera di ID incantesimo in stile ElvUI per debuff arbitrari."
L["Open this section to enable or disable rounded frame textures and its per-surface toggles."] = "Apri questa sezione per attivare o disattivare le texture dei riquadri arrotondati e i relativi interruttori per superficie."
