L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Quando attivo, WoW gestisce le icone dei benefici. Le categorie nascoste di MSUF e il posizionamento personalizzato dei benefici non filtrano i benefici renderizzati da Blizzard, quindi Skyfury o Earth Shield possono ancora comparire."
L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Quando attivo, WoW gestisce le icone dei malus. Le categorie nascoste di MSUF e il posizionamento personalizzato dei malus non filtrano i malus renderizzati da Blizzard."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Quando attivo, WoW gestisce le icone difensive. Il posizionamento e lo stile personalizzati di MSUF si applicano solo quando questa opzione e disattivata o il renderer e MSUF Custom."
