L["Profile-wide · follows the active Party, Raid, or Mythic Raid frame appearance"] = "Per tutto il profilo · segue l’aspetto dei riquadri attivi di gruppo, incursione o incursione mitica"
L["Keep tanks and manually pinned group members in one stable strip without removing them from the normal Party or Raid frames."] = "Mantieni i difensori e i membri fissati manualmente in una striscia stabile senza rimuoverli dai normali riquadri di gruppo o incursione."
L["Profile-wide layout · character-specific pins · available in parties and raids · inherits the active group-frame appearance and click-cast behavior."] = "Disposizione per tutto il profilo · fissaggi per personaggio · disponibile in gruppi e incursioni · eredita aspetto e lancio con clic dei riquadri di gruppo attivi."
L["Waiting — enable Party frames first."] = "In attesa: attiva prima i riquadri gruppo."
L["Waiting — none of your saved players are in the current group."] = "In attesa: nessun giocatore salvato è nel gruppo attuale."
L["Ready — pin a group member or include tanks automatically."] = "Pronto: fissa un membro del gruppo o includi automaticamente i difensori."
L["Ready — join a party or raid to show Priority Frames."] = "Pronto: entra in un gruppo o incursione per mostrare i riquadri prioritari."
L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."] = "Passa su un riquadro MSUF di gruppo, incursione o prioritario e premi questo tasto per fissare o liberare il giocatore."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."] = "Nessun fissaggio manuale. In gruppo, passa su un riquadro MSUF di gruppo, incursione o prioritario e premi il tasto."
L["Use the hover hotkey above to add or remove players."] = "Usa il tasto al passaggio qui sopra per aggiungere o rimuovere giocatori."
L["Saved · not grouped"] = "Salvato · non in gruppo"
L["Saved · not in current group"] = "Salvato · assente dal gruppo attuale"
L["Saved · Party frames disabled"] = "Salvato · riquadri gruppo disattivati"
L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."] = "Aggancia la striscia al contenitore attivo di gruppo, incursione o incursione mitica, oppure scegli Posizione libera e sistemala in modalità modifica."
L["Right of group frames"] = "A destra dei riquadri di gruppo"
L["Left of group frames"] = "A sinistra dei riquadri di gruppo"
L["Above group frames"] = "Sopra i riquadri di gruppo"
L["Below group frames"] = "Sotto i riquadri di gruppo"
L["The strip follows the active Party, Raid, or Mythic Raid container automatically."] = "La striscia segue automaticamente il contenitore attivo di gruppo, incursione o incursione mitica."
L["In party"] = "In gruppo"
L["In raid"] = "In incursione"
L["Not grouped"] = "Non in gruppo"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."] = "I riquadri prioritari tengono difensori automatici e membri fissati in una striscia aggiuntiva stabile. In gruppo ereditano i riquadri gruppo; in incursione quelli attivi di incursione o incursione mitica. I riquadri di base corrispondenti devono essere attivi. Apri Riquadri di gruppo > Priorità per scegliere chi appare, il tasto e la posizione."
L["Free position uses the dedicated Priority Frames mover."] = "La posizione libera usa il trascinatore dedicato ai riquadri prioritari."
L["How do Priority Frames work?"] = "Come funzionano i riquadri prioritari?"
L["Opens: Group Frames > Priority"] = "Apre: Riquadri di gruppo > Priorità"
L["Pin or unpin hovered group member"] = "Fissa o libera il membro sotto il puntatore"
L["Priority Frames hotkey"] = "Tasto dei riquadri prioritari"
L["Left-click and press a key. Right-click, Backspace, or Delete clears it. Existing bindings are never replaced without confirmation."] = "Fai clic sinistro e premi un tasto. Clic destro, Backspace o Canc lo rimuovono. Le assegnazioni esistenti non vengono mai sostituite senza conferma."
