L["Health and Power use separate gradient colors. Choosing a color creates a custom Bars override for the selected scope."] = "Salute e Potenza utilizzano colori sfumati separati. La scelta di un colore crea una sostituzione Bars personalizzata per l'ambito selezionato."
L["UPGRADED TO MSUF %s"] = "AGGIORNATO A MSUF %s"
L["Your MSUF 6.0 highlights"] = "I tuoi punti salienti di MSUF 6.0"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "Il tuo profilo attuale rimane invariato. Consulta le nuove funzionalità %d e scegli solo ciò che desideri configurare."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "PROFILO ATTUALE: %s - NESSUNA IMPOSTAZIONE VERRÀ CAMBIATA"
L["Start %d-highlight tour"] = "Avvia il tour dei momenti salienti di %d"
L["Review the release highlights without changing your current profile."] = "Rivedi i punti salienti della versione senza modificare il tuo profilo attuale."
L["Review exactly what you would skip before closing the tour."] = "Rivedi esattamente cosa salteresti prima di chiudere il tour."
L["About two minutes. You can leave at any point and configure each area later."] = "Circa due minuti. Puoi uscire in qualsiasi momento e configurare ciascuna area in un secondo momento."
L["Highlight %d of %d"] = "Evidenzia %d di %d"
L["WHY IT MATTERS"] = "PERCHÉ È IMPORTANTE"
L["Finish tour"] = "Termina il giro"
L["Next highlight"] = "Evidenziazione successiva"
L["Mark this highlight as reviewed and continue."] = "Contrassegna questo momento saliente come rivisto e continua."
L["Back"] = "Indietro"
L["Skip tour"] = "Salta il giro"
L["See the remaining highlights before deciding to skip them."] = "Guarda i restanti punti salienti prima di decidere di saltarli."
L["Skip %d remaining highlights?"] = "Saltare i punti salienti rimanenti di %d?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "Il tuo profilo resterà al sicuro, ma lascerai inesplorate queste %d nuove aree di configurazione:"
L["Show me the highlights"] = "Mostrami i punti salienti"
L["Skip all %d and continue"] = "Salta tutto %d e continua"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "Saltando si chiude solo questo tour di rilascio. Ogni impostazione rimane disponibile nel Menu2."
L["Custom Aura tracking on Unitframes"] = "Tracciamento personalizzato dell'aura su Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "Crea fino a tre corsie personalizzate su Giocatore, Bersaglio, Focus e Boss, inserisci SpellID esatti di buff o debuff e traccia i tuoi DoT sul Bersaglio con una corsia curata per classe."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "I tuoi riquadri MSUF possono agire come tracker focalizzati in stile WeakAura con icone, timer, barre di durata ed effetti di tinta, bordo, bagliore o impulso a pieno formato."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "tre tracker Aura personalizzati per Unitframe supportato, liste bianche esatte di incantesimi ed effetti full-frame"
L["Build a Custom tracker"] = "Costruisci un tracker personalizzato"
L["Aura settings in the right place"] = "Impostazioni delle aure al posto giusto"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "La configurazione e lo stile individuale si trovano ora nei menu corrispondenti dei riquadri unità e gruppo/incursione. Aspetto > Aure contiene gli stili condivisi estesi."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "Configura ogni riquadro nel suo contesto, poi usa Aure per condividere forme delle icone, bordi, ombre, colori e spaziatura."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "controlli delle aure per riquadro e stile condiviso esteso in Aspetto > Aure"
L["Open shared Aura styles"] = "Apri gli stili condivisi delle aure"
L["Adaptive Party and Raid layouts"] = "Layout adattivi per Party e Raid"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "Gruppo, Incursione e Incursione mitica hanno ottenuto layout adattivi con ridimensionamento, filtri e liste nere delle aure per corsia, una pagina dedicata al Dispel Overlay, e decidi tu per ogni gruppo se i riquadri li disegna MSUF o Blizzard."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "Una sola configurazione di gruppo può seguirti da un gruppo da cinque fino all'incursione, e decidi corsia per corsia quali aure possono comparire."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "i layout adattivi e il ridimensionamento, i filtri e le liste nere delle aure di gruppo, la pagina Dispel Overlay e il controllo del provider per gruppo"
L["Open Group Layout"] = "Apri il layout del gruppo"
L["New health values and text formats"] = "Nuovi valori di salute e formati di testo"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "Il testo della salute può mostrare valori abbreviati o completi con una formattazione più coerente, e il nuovo overlay della salute massima persa evidenzia la salute massima ridotta su riquadri singoli e di gruppo."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Puoi scegliere la leggibilità compatta o i numeri esatti senza rinunciare al layout che già utilizzi."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "le nuove abbreviazioni della salute, i valori completi, i formati di testo e l'overlay della salute massima persa"
L["Open HP Text Editor"] = "Apri l'editor del testo della salute"
L["More flexible class resources"] = "Risorse di classe più flessibili"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Le risorse di classe hanno ottenuto layout separati, forme aggiuntive e colori più fini per slot e a stato completo."
L["You can move class information where your eyes already are and make important states easier to read."] = "Puoi spostare le informazioni sulla classe dove sono già i tuoi occhi e rendere più facile la lettura degli stati importanti."
L["detached class resources, new shapes and per-state colors"] = "risorse di classe indipendenti, nuove forme e colori per stato"
L["Configure Class Resources"] = "Configura le risorse della classe"
L["Cast target text"] = "Trasmetti il testo di destinazione"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Le barre di lancio Bersaglio, Concentrazione e Boss ora possono mostrare chi sta prendendo di mira l'incantesimo corrente, con uno stile di testo dedicato."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Puoi identificare la destinazione di un cast importante senza spostare l'attenzione dalla barra del cast."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "nomi dei bersagli di lancio e il loro stile di testo sui riquadri Target, Focus e Boss"
L["Open Target Cast Bar"] = "Apri la barra di cast del bersaglio"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "Rivedi o salta i punti salienti della versione sulla Dashboard prima di utilizzare le azioni di primo caricamento."
L["Priority Frames for the units that matter"] = "Riquadri prioritari per le unità che contano"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "Fissa fino a cinque membri del gruppo a mano, oppure lascia che MSUF scelga i tank automaticamente, e dai loro una striscia dedicata che non si riordina mai a metà combattimento."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "Le persone che devi tenere d'occhio mantengono un posto fisso sullo schermo, con l'aspetto di gruppo o incursione e il click-casting che avevano già."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "i riquadri prioritari, il fissaggio manuale e automatico e la loro collocazione"
L["Set up Priority Frames"] = "Configura i riquadri prioritari"
L["One Colors page with click-to-paint"] = "Una pagina Colori con la pittura al clic"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "Tutti i colori sono confluiti in un'unica pagina, divisa negli spazi di lavoro Giocatore e Bersaglio, Gruppo e Incursione, Barra di lancio, Aure, Energia e Risorse di classe, ognuno con la propria anteprima dal vivo."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "Puoi cliccare l'elemento nell'anteprima per colorarlo invece di cercare il campione giusto, e riutilizzare qualsiasi colore da una tavolozza recente o salvata."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "la pagina Colori ricostruita, le anteprime da colorare al clic, le tavolozze e il nuovo selettore di colore"
L["Open the Colors page"] = "Apri la pagina Colori"
L["One 0-30 layer scale for everything"] = "Un'unica scala di livelli 0-30 per tutto"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "Testi, icone di stato, aure, bordi, contorni delle barre, indicatori di gruppo e risorse di classe si ordinano tutti su un'unica scala di livelli 0-30."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "Decidi esattamente cosa viene disegnato davanti a cosa, e la panoramica dei livelli accanto a qualsiasi cursore di livello mostra l'intera pila in una volta."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "la scala di livelli 0-30 valida per tutto l'addon e la panoramica dei livelli"
L["MSUF Edit Mode, rebuilt"] = "La modalità modifica di MSUF, ricostruita"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "La modalità modifica ha guadagnato una barra degli strumenti agganciabile, menu rapidi ridisegnati su ogni riquadro e Annulla e Ripeti che si comportano come nel menu."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "Puoi spostare, ridimensionare e copiare i riquadri direttamente sullo schermo e tornare indietro da qualsiasi errore senza riaprire il menu."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "la nuova barra degli strumenti della modalità modifica, i suoi menu rapidi e l'Annulla/Ripeti condiviso"
L["Start Edit Mode"] = "Avvia la modalità modifica"
L["Spell Indicators on Group Frames"] = "Spell Indicators sui riquadri di gruppo"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "Traccia buff scelti sui riquadri di gruppo e incursione come icona, quadrato, barra o numero, con liste di incantesimi personalizzate e indicatori d'angolo."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "Vedi gli external mancanti o in scadenza e i buff chiave direttamente sui riquadri, con bagliori di scadenza, evidenziazione della barra della salute ed effetti a riquadro intero."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "gli Spell Indicators con liste di aure personalizzate, indicatori d'angolo e avvisi di scadenza"
L["Open Spell Indicators"] = "Apri gli Spell Indicators"
L["Fill Direction for Health and Power"] = "Direzione di riempimento di Salute e Potere"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "Ogni riquadro unità può riempire Salute e Potere da sinistra a destra, da destra a sinistra, dal basso in alto o dall'alto in basso."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "I layout verticali o speculari diventano una scelta per riquadro: qualcosa che nessun altro addon di unit frame offre attualmente."
L["the per-frame Fill Direction control for Health and Power bars"] = "il controllo per riquadro della direzione di riempimento delle barre di Salute e Potere"
L["Choose a Fill Direction"] = "Scegli una direzione di riempimento"
L["Portraits: attached, detached or overlay"] = "Ritratti: agganciato, staccato o overlay"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "I ritratti possono restare agganciati, fluttuare liberi o essere disegnati come overlay nella barra della salute, con dimensioni indipendenti, ancoraggio a nove punti, opacità e zoom trascinabile."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "Diventano possibili ritratti rettangolari o in filigrana, e gli anelli Relief più i bordi che seguono la forma incorniciano ritratti quadrati, circolari, arrotondati e a diamante."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "i nuovi posizionamenti dei ritratti, gli anelli Relief e i bordi che seguono la forma"
L["Open Portrait settings"] = "Apri le impostazioni del ritratto"
L["Status icon packs"] = "Pacchetti di icone di stato"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "Ruolo, capogruppo, segnalino, controllo preparazione e ogni altra icona di stato possono passare tra dodici stili inclusi o icone personalizzate, per indicatore."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "Le icone di stato possono finalmente adattarsi al tuo stile di interfaccia invece della grafica Blizzard, e i pacchetti esterni possono registrarsi tramite SharedMedia."
L["the twelve status icon styles and per-indicator custom icons"] = "i dodici stili di icone di stato e le icone personalizzate per indicatore"
L["Pick an icon style"] = "Scegli uno stile di icone"
L["Old"] = "Vecchio"
