L["Double-click or use the settings button to open this element's settings."] = "Fare doppio clic o utilizzare il pulsante Impostazioni per aprire le impostazioni di questo elemento."
L["Right-click opens quick actions."] = "Facendo clic con il tasto destro si aprono le azioni rapide."
L["double-click/settings opens options - right-click actions - arrows nudge"] = "facendo doppio clic su /settings si aprono le opzioni - azioni del tasto destro - spinta delle frecce"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "trascina le maniglie - fai doppio clic su /settings apre le opzioni - fai clic con il pulsante destro del mouse - Ctrl+zoom rotella"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "Fare clic su una maniglia per selezionare - fare doppio clic su /settings per aprire le opzioni - fare clic con il pulsante destro del mouse su azioni - Ctrl+zoom rotella"
L["Preview tip: drag handles to move, double-click or use settings to open options, right-click for actions."] = "Suggerimento per l'anteprima: trascina le maniglie per spostare, fai doppio clic o utilizza le impostazioni per aprire le opzioni, fai clic con il pulsante destro del mouse per le azioni."
