L["Class resource preview and quick setup"] = "Anteprima delle risorse della classe e configurazione rapida"
L["Preview controls = inspect layouts and states · MSUF Edit Mode = whole-frame placement"] = "Controlli di anteprima = ispeziona layout e stati · Modalità modifica MSUF = posizionamento dell'intero riquadro"
L["Drag = inner position · gear/double-click = options · right-click = actions · Ctrl-wheel/drag = zoom/pan · Edit Mode = whole frame"] = "Trascina = posizione interna · ingranaggio/double-click = opzioni · clic destro = azioni · Ctrl-ruota/drag = zoom/pan · Modalità modifica = intero riquadro"
L["%s is highlighted. Adjust it live, keep it as is, or continue."] = "%s è evidenziato. Modificalo in tempo reale, mantienilo così com'è o continua."
L["Your focus: %s, with %s information."] = "Il tuo focus: %s, con informazioni su %s."
L["Choose one answer in each row. You can skip this personal step at any time."] = "Scegli una risposta in ogni riga. Puoi saltare questo passaggio personale in qualsiasi momento."
L["Drag whole frames, use arrows for precision, and Exit to keep your placement."] = "Trascina interi riquadri, usa le frecce per la precisione ed Esci per mantenere il posizionamento."
L["Start with Preview, then follow each highlighted frame section."] = "Inizia con Anteprima, quindi segui ciascuna sezione del riquadro evidenziato."
L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Obiettivo del raid: confronta gli ambiti del Raid e del Mitico prima di rivedere ciascuna sezione evidenziata."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "Focus individuale: mantenere le impostazioni predefinite del gruppo o preparare l'ambito del gruppo per gruppi occasionali."
L["Dungeon focus: begin with Party or Mythic scope, then review each highlighted section."] = "Focus sui dungeon: inizia con l'ambito Party o Mitico, quindi rivedi ciascuna sezione evidenziata."
L["Compare the Party, Raid or Mythic scope that matters to you, then follow the highlights."] = "Confronta l'ambito del Party, del Raid o del Mitico che ti interessa, quindi segui i punti salienti."
L["Sample = visual only · tests = temporary · scope = shared/unit/group"] = "Esempio = solo visivo · test = temporaneo · ambito = condiviso/unit/group"
L["Simulate casts here; position castbar handles in Preview or MSUF Edit Mode."] = "Simula qui i calchi; posizionare le maniglie della barra di cast in modalità Anteprima o Modifica MSUF."
L["Use the scope selector for shared, unit and group text; compare readability in Preview."] = "Utilizzare il selettore dell'ambito per testo condiviso, unitario e di gruppo; confrontare la leggibilità in Anteprima."
L["Live/Dummy = display only · colored handles = saved positions · scope = shared/unit/group/custom"] = "Live/Dummy = solo visualizzazione · maniglie colorate = posizioni salvate · ambito = condiviso/unit/group/custom"
L["Use the interactive preview for layouts and states; use Edit Mode for whole-frame placement."] = "Utilizza l'anteprima interattiva per layout e stati; utilizzare la modalità Modifica per il posizionamento dell'intero riquadro."
L["Finish with a profile check and export a backup of your setup."] = "Termina con un controllo del profilo ed esporta un backup della tua configurazione."
L["Review your choices and skipped areas. Finish adds no extra setting changes."] = "Rivedi le tue scelte e le aree saltate. La finitura non aggiunge ulteriori modifiche alle impostazioni."
L["Clarity focus: prefer the simplest readable option in each highlighted section."] = "Focus sulla chiarezza: preferisci l'opzione più semplice e leggibile in ciascuna sezione evidenziata."
L["Combat-detail focus: inspect indicators, timers and visibility in each highlighted section."] = "Focus sui dettagli del combattimento: controlla gli indicatori, i timer e la visibilità in ogni sezione evidenziata."
L["Review the highlighted sections; previews update while your changes autosave."] = "Rivedere le sezioni evidenziate; le anteprime si aggiornano mentre le modifiche vengono salvate automaticamente."
