L["What you can move"] = "Cosa puoi spostare"
L["Unitframes, supported castbars, group containers, aura groups and the tooltip preview. Boss 1 moves the shared Boss layout."] = "Unitframe, castbar supportati, contenitori di gruppo, gruppi di aura e anteprima del tooltip. Il Boss 1 sposta il layout del Boss condiviso."
L["Drag, select and align"] = "Trascina, seleziona e allinea"
