L["Undo, Cancel All, Exit"] = "Annulla, Annulla tutto, Esci"
L["Undo and Redo affect individual moves. Cancel All restores the entry snapshot; Exit keeps your work."] = "Annulla e Ripeti influiscono sulle singole mosse. Annulla tutto ripristina l'istantanea della voce; L'uscita mantiene il tuo lavoro."
L["Combat pauses safely"] = "Il combattimento si ferma in sicurezza"
L["Combat closes the menu and Edit Mode but keeps changes made so far. Reopen MSUF afterward to resume here."] = "Il combattimento chiude il menu e la modalità Modifica ma mantiene le modifiche apportate finora. Riaprire MSUF in seguito per riprendere qui."
