L["Spell-specific channel tick markers"] = "Indicatori di tick del canale specifici dell'incantesimo"
L["Runs a short castbar for the global cooldown whenever an instant spell triggers it.\n\nThe fill and time text are driven natively by the client from the real (haste-scaled) GCD duration - no per-frame addon work while the bar runs. A real cast, channel or empower always takes priority."] = "Mostra una breve barra di lancio per il tempo di recupero globale quando un incantesimo istantaneo lo attiva.\n\nIl riempimento e il testo del tempo sono gestiti nativamente dal client in base alla durata reale del GCD (scalata con la celerità) - nessun lavoro dell'addon per riquadro mentre la barra è attiva. Un lancio reale, un incanalamento o un incantesimo potenziato ha sempre la priorità."
L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Mostra i separatori di spunta sulla barra di cast del giocatore durante la canalizzazione.\n\nGli incantesimi supportati utilizzano il loro conteggio di tick effettivo, inclusi i talenti supportati e le modifiche alla durata del canale. I canali non supportati mantengono cinque linee di fallback equidistanti. Le impostazioni di spunta del canale personalizzato sovrascrivono il layout automatico.\n\nI marcatori sono guidati da eventi e non aggiungono polling ricorrente del canale."
L["Class Color (Reaction fallback)"] = "Colore classe (ripiego reazione)"
L["Ready color (kick available)"] = "Colore pronto (calcio disponibile)"
L["Not ready color (kick on cooldown)"] = "Colore non pronto (avvio del tempo di recupero)"
L["PvP Flag (War Mode/PvP)"] = "Bandiera PvP (modalità Guerra/PvP)"
L["Abbreviate HP values (K/M)"] = "Abbreviare i valori HP (K/M)"
L["For specializations that use mana alongside another resource."] = "Per le specializzazioni che utilizzano il mana insieme a un'altra risorsa."
L["Smooths resource changes. Runes, Essence recharge, and timers keep their own animation."] = "Agevola i cambiamenti delle risorse. Rune, ricarica dell'essenza e timer mantengono la propria animazione."
L["Exact Spell IDs are used when Blizzard exposes them."] = "Gli ID degli incantesimi esatti vengono utilizzati quando Blizzard li espone."
L["Reverses only the swipe overlay. Icon size and position stay unchanged."] = "Inverte solo la sovrapposizione dello scorrimento. La dimensione e la posizione dell'icona rimangono invariate."
L["Only relevant sorting methods are shown for buffs and debuffs."] = "Vengono mostrati solo i metodi di ordinamento rilevanti per buff e debuff."
L["Reversed flips the complete priority order."] = "Invertito capovolge l'ordine di priorità completo."
