L["Copies the complete Group Aura configuration, including Buff/Debuff filters, exact and category blacklists, layout, cooldown presentation, Strata, and dispel options."] = "Copia la configurazione completa dell'Aura di gruppo, inclusi i filtri Buff/Debuff, liste nere esatte e di categoria, layout, presentazione del tempo di recupero, Strati e opzioni di dispersione."
L["Copies every text slot with its content, size and position, plus this unit's font overrides: font, outline, shadow, text color and name shortening."] = "Copia ogni slot di testo con contenuto, dimensione e posizione, oltre alle sostituzioni del carattere di questa unità: carattere, contorno, ombra, colore del testo e abbreviazione dei nomi."
