L["Midnight keeps the stock blue accent. Class color follows this character; the accent applies after a UI reload."] = "Midnight mantiene l'accento blu originale. Colore della classe segue questo personaggio; l'accento si applica dopo un ricaricamento dell'interfaccia."
L["The menu accent color is baked in while the menu is built, so a UI reload is required to apply it.\n\nReload now?"] = "Il colore d'accento del menu viene integrato durante la costruzione del menu, quindi è necessario ricaricare l'interfaccia per applicarlo.\n\nRicaricare ora?"
L["Menu accent colors"] = "Colori d'accento del menu"
L["The MSUF menu can now follow your class color, a curated preset like Ember, Jade or Violet, or any custom color."] = "Il menu di MSUF può ora seguire il colore della tua classe, un preset curato come Ember, Jade o Violet, o qualsiasi colore personalizzato."
L["The whole menu re-tints to your accent - surfaces, navigation and controls - applied after a UI reload."] = "L'intero menu si tinge del tuo accento - superfici, navigazione e controlli - applicato dopo un ricaricamento dell'interfaccia."
L["The accent colors navigation, tabs and highlights; panels stay midnight unless you turn on Tint menu surfaces. Applied after a UI reload."] = "L'accento colora la navigazione, le schede e le evidenziazioni; le superfici restano midnight a meno che non attivi «Colora le superfici del menu». Applicato dopo un ricaricamento dell'interfaccia."
L["Tint menu surfaces"] = "Colora le superfici del menu"
L["Zoom %d%%"] = "Zoom %d%%"
L["Opacity %d%%"] = "Opacità %d%%"
L["Off (default): the accent colors buttons, tabs and highlights while panels stay midnight. On: panels, borders and the navigation rail are rotated onto the accent hue too. Success, warning and danger colors never change."] = "Disattivato (predefinito): l'accento colora pulsanti, schede ed evidenziazioni mentre le superfici restano midnight. Attivato: anche superfici, bordi e barra di navigazione vengono ruotati sulla tonalità dell'accento. I colori di successo, avviso e pericolo non cambiano mai."
L["class-color, preset and custom accent options for the MSUF menu"] = "opzioni di accento per colore di classe, preset e colore personalizzato per il menu di MSUF"
L["Pick a menu accent"] = "Scegli un accento del menu"

-- 6.0 upgrade highlight: the rebuilt rounded corner style.
L["Rounded frames, corner for corner"] = "Cornici arrotondate, angolo per angolo"
L["Rounded unit and group frames now share one clean corner style with five strength levels, used by Health, embedded or detached Power, frame outlines and the aggro, dispel and highlight borders."] = "Le cornici di unità e di gruppo arrotondate condividono ora un unico stile d'angolo pulito con cinque livelli di intensità, usato da Salute, Energia integrata o staccata, contorni della cornice e bordi di aggro, dissoluzione ed evidenziazione."
L["Every rounded element follows the same geometry, so corners no longer disagree with each other or lose their mask after a reload."] = "Ogni elemento arrotondato segue la stessa geometria, così gli angoli non si contraddicono più e non perdono la maschera dopo un ricaricamento."
L["the rebuilt rounded corner style and its five strength levels"] = "lo stile d'angolo arrotondato ricostruito e i suoi cinque livelli di intensità"
L["Open Rounded Texture"] = "Apri Texture arrotondata"

