L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Uso: /msuf load <name>. Digita /msuf profile per elencarli."
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' corrisponde a più profili. Digita il nome completo."
L["|cffff0000MSUF:|r Unknown profile '%s'. Type /msuf profile to list them."] = "|cffff0000MSUF:|r Profilo sconosciuto '%s'. Digita /msuf profile per elencarli."
