L["|cffffcc00MSUF:|r Usage: /msuf delete <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r Uso: /msuf delete <name>. Digita /msuf profile per elencarli."
L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r Ripeti |cffffff00/msuf delete %s|r per eliminare definitivamente quel profilo."
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r Non è possibile ripristinare un profilo in combattimento."
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r Questo ripristina tutte le impostazioni del profilo '%s', non solo le posizioni."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r Digita |cffffff00/msuf default confirm|r per procedere."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r Digita prima |cffffff00/msuf default|r, poi conferma."
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r Riquadro sconosciuto '%s'. Prova player, target, focus, pet, boss o priority."
