L["Copy Party settings"] = "Copia le impostazioni del gruppo"
L["Colors follow this frame's effective Health Color Scheme."] = "I colori seguono lo schema colori della salute effettivo di questo riquadro."
L["Uses the selected slot's Custom Spell color or the shared Corner Aggro color."] = "Usa il colore incantesimo personalizzato della posizione scelta o il colore aggro d'angolo condiviso."
L["Uses this Fonts scope's effective Default font color."] = "Usa il colore predefinito effettivo di questo ambito dei caratteri."
L["A matched resource background is derived from Health instead."] = "Uno sfondo della risorsa abbinato viene invece derivato dalla salute."
L["The resource color follows the current unit. A matched background is derived from Health instead."] = "Il colore della risorsa segue l'unità attuale. Uno sfondo abbinato viene invece derivato dalla salute."
L["The resource color follows Player power. A matched background is derived from Health instead."] = "Il colore della risorsa segue la risorsa del giocatore. Uno sfondo abbinato viene invece derivato dalla salute."
L["The foreground follows the selected HP color mode. Dark Mode uses the shared dark-tone control."] = "Il primo piano segue la modalità colore salute scelta. La modalità scura usa il controllo del tono scuro condiviso."
L["Foreground follows the selected group color mode; editable group colors are shared by Party, Raid and Mythic Raid."] = "Il primo piano segue la modalità colore del gruppo scelta; i colori di gruppo modificabili sono condivisi tra Gruppo, Incursione e Incursione mitica."
L["Health and Power gradient colors for the selected Bars scope."] = "Colori sfumatura di salute e risorsa per l'ambito delle barre scelto."
L["Colors available to the border modes in this card."] = "Colori disponibili per le modalità bordo di questa scheda."
L["Shared castbar background and outline colors."] = "Colori condivisi di sfondo e contorno della barra di lancio."
L["Player colors follow the active override mode."] = "I colori del giocatore seguono la modalità di sostituzione attiva."
L["The shown colors follow the selected indicator style."] = "I colori mostrati seguono lo stile dell'indicatore scelto."
L["These colors are shared from the Colors page."] = "Questi colori provengono dalla pagina Colori."
L["Used when melee-range coloring is enabled."] = "Usato quando la colorazione per la portata in mischia è attiva."
L["Used by the Castbar icon-border style."] = "Usato dallo stile del bordo icona della barra di lancio."
L["Used only when the power bar is detached from the frame."] = "Usato solo quando la barra della risorsa è staccata dal riquadro."
L["Outline and fill behavior."] = "Comportamento di contorno e riempimento."
L["Opacity values used by range and offline states."] = "Valori di opacità usati dagli stati di portata e non in linea."
L["Width can use manual bounds or follow another frame."] = "La larghezza può usare limiti manuali o seguire un altro riquadro."
L["Power textures live on the Bars page."] = "Le texture della risorsa si trovano nella pagina Barre."
L["When anchored here, Player power settings are managed by Class Resources."] = "Se ancorata qui, le impostazioni della risorsa del giocatore sono gestite dalle Risorse di classe."
L["Font face follows Shared; text and color mode mirror Player HP."] = "Il carattere segue Condiviso; testo e modalità colore rispecchiano la salute del giocatore."
L["Local HP text uses shared face settings and a fixed white color."] = "Il testo salute locale usa le impostazioni del carattere condivise e un bianco fisso."
L["Synchronized with Text Colors in the Fonts menu for this scope."] = "Sincronizzato con Colori del testo nel menu Caratteri per questo ambito."
L["Open the shared font and colors used by every Aura scope."] = "Apre il carattere e i colori condivisi usati da tutti gli ambiti delle aure."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "Colora le barre della salute dei riquadri unità quando una condizione di debuff configurata è attiva."
L["Shows a symbol naming the dispel type of an active debuff."] = "Mostra un simbolo che indica il tipo di dissoluzione di un debuff attivo."
L["Shows the raid subgroup number from the raid roster."] = "Mostra il numero del sottogruppo dall'elenco dell'incursione."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "Mostra il numero del sottogruppo. I riquadri del gruppo lo mostrano solo in una vera incursione."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "Indipendente dal passaggio del mouse. Evidenzia il bersaglio attuale nei tipi di riquadro di gruppo scelti."
L["Configure target highlighting in Appearance > Miscellaneous > Frame Highlights."] = "Configura l'evidenziazione del bersaglio in Aspetto > Varie > Evidenziazioni riquadro."
L["Configure the color used by the Solid and Custom portrait border styles."] = "Imposta il colore degli stili del bordo del ritratto Pieno e Personalizzato."
L["Configure the optional portrait background color."] = "Imposta il colore di sfondo opzionale del ritratto."
L["Configure the Party portrait border color and opacity."] = "Imposta colore e opacità del bordo del ritratto del gruppo."
L["Scales frame size, fonts, and icons proportionally."] = "Ridimensiona proporzionalmente riquadro, caratteri e icone."
L["Buff/debuff positions stay relative to their anchors."] = "Le posizioni di buff e debuff restano relative ai loro ancoraggi."
L["Automatically scale by group size."] = "Ridimensiona automaticamente in base alla dimensione del gruppo."
L["Drag rows with mouse to reorder."] = "Trascina le righe con il mouse per riordinarle."
