L["Color for the selected text indicator. Right-click to follow the frame font color again."] = "Colore dell'indicatore di testo selezionato. Clic destro per tornare a seguire il colore del carattere del riquadro."
L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "Il testo della barra di lancio segue le impostazioni condivise dei caratteri finché non riceve un colore proprio."
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "Lo stile del carattere segue il menu Caratteri di questo riquadro; il colore si imposta per indicatore."
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "Ogni testo della barra di lancio può sostituire il colore condiviso. Il testo del bersaglio esiste solo su Bersaglio e Focus."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "Colore di un singolo indicatore di testo su un riquadro. Senza colore proprio l'indicatore segue il carattere del riquadro."
