L["Shared icon shape"] = "Forma icona condivisa"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Le modalità di visibilità si applicano solo ai frame di unità e di gruppo. Le descrizioni delle aure usano i propri interruttori Mostra descrizione; nemmeno Mai le sovrascrive. Le aure riutilizzano solo l'aspetto Blizzard/MSUF selezionato e la posizione del cursore."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "Si applica all'intera barra di lancio: barra, icona, tutti i testi, effetti e bordo. Tutti gli elementi MSUF condividono questo ordine 0-30; ogni parte del livello 30 viene disegnata sopra ogni parte del livello 29."
