--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "Sempre nascosto"
L["Blizzard Raid Manager"] = "Gestore incursioni di Blizzard"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "La linguetta di Blizzard sul bordo sinistro dello schermo con controllo prontezza, simboli d'incursione e filtri dei ruoli. È un unico riquadro condiviso, quindi questa impostazione è la stessa per Gruppo, Incursione e Incursione mitica."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "Dissolve il gestore incursioni finché il mouse non lo tocca. Controllo prontezza, simboli d'incursione e filtri dei ruoli restano raggiungibili, e un pannello aperto resta visibile finché non lo richiudi."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "Mantiene il gestore incursioni sempre invisibile e trasparente ai clic. Torna indietro per raggiungere di nuovo i suoi pulsanti."
L["Show on mouseover"] = "Mostra al passaggio del mouse"
L["Automatic"] = "Automatico"
L["Always visible"] = "Sempre visibile"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "Nasconde il gestore incursioni finché MSUF fornisce i riquadri di gruppo attivi, altrimenti lo lascia a WoW. MSUF si è sempre comportato così."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "Mantiene raggiungibile il gestore incursioni anche con i riquadri di gruppo di MSUF attivi. Usalo se vuoi ancora il suo controllo prontezza, i simboli d'incursione e i filtri dei ruoli."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "Condiviso da Gruppo, Incursione e Incursione mitica. Automatico tiene nascosta la linguetta finché MSUF fornisce i riquadri di gruppo."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s rilevato: l’ancoraggio globale segue il gestore dei tempi di recupero essenziali. Disattivalo con Cooldown nella modalità modifica di MSUF."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s rilevato: l’ancoraggio al gestore dei tempi di recupero è disattivato. Attivalo con Cooldown nella modalità modifica di MSUF."
L["Cooldown Manager anchoring (%s)"] = "Ancoraggio al gestore dei tempi di recupero (%s)"
L["Global anchor (%s Anchor)"] = "Ancoraggio globale (ancoraggio %s)"
L["Fades all four outer edges; 0% keeps the original texture."] = "Sfuma tutti e quattro i bordi esterni; 0% mantiene la texture originale."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1 mostra la dimensione in pixel dell'aura impostata."
L["Aura Options"] = "Opzioni aura"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "Le Opzioni aura e lo Stile dell'Aura appartengono a questo UnitFrame. Aspetto globale delle icone: Aspetto > Stile dell'Aura."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "Al di sotto di questo valore il tempo rimanente può mostrare un decimale. Imposta 0 per usare solo secondi interi."
L["Buff Appearance"] = "Aspetto dei buff"
L["Debuff Appearance"] = "Aspetto dei malus"
L["Global Aura Appearance: Buffs"] = "Aspetto globale delle aure: Benefici"
L["Global Aura Appearance: Debuffs"] = "Aspetto globale delle aure: Malus"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "I colori del timer sono condivisi dalle aure dal vivo di unità/gruppo e da ogni anteprima. I colori del bordo e dell'ombra delle icone si trovano in Aspetto > Aure e sono separati per tipo di aura."
L["Click to open the setting that enables this layer."] = "Fai clic per aprire l'impostazione che attiva questo livello."
L["Controls native Aura tooltips for Spell Icons only."] = "Controlla le descrizioni native delle aure solo per le Icone incantesimi."
L["Cooldown text format"] = "Formato del testo di recupero"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "Copia la presentazione di buff, debuff, difensivi esterni e Icone incantesimi, incluso lo zoom dell'icona, il testo, lo sweep, le barre della durata e l'ordinamento. Le Opzioni aura, le Icone incantesimi monitorate e il tema globale Aspetto restano invariati."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "Copia visibilità, disposizione, filtri, liste nere esatte e per categoria, livello di sovrapposizione e opzioni di dissolvimento delle aure di gruppo. Lo Stile dell'Aura e il tema globale Aspetto restano invariati."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "Copia visibilità delle aure, disposizione, filtri, liste nere, configurazione delle aure personalizzate e incantesimi monitorati di questo UnitFrame. Lo Stile dell'Aura e il tema globale Aspetto restano invariati."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "Copia la presentazione di buff, debuff, aure personalizzate, difensivi del giocatore e DoT sul bersaglio di questo UnitFrame, inclusi testo, sweep, zoom dell'icona, barre della durata, pandemia ed effetti a riquadro intero. Le Opzioni aura e il tema globale Aspetto restano invariati."
L["Drag background (%dx)"] = "Trascina lo sfondo (%dx)"
L["Drag to move. Arrow keys nudge."] = "Trascina per spostare. I tasti freccia regolano con precisione."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "Modalità sblocco EllesmereUI"
L["Exact X coordinate"] = "Coordinata X esatta"
L["Exact Y coordinate"] = "Coordinata Y esatta"
L["Fit shows the complete aura layout."] = "Adatta mostra la disposizione completa delle aure."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "Tema globale Aspetto selezionabile solo per tipo di aura. Disposizione, filtri, timer, testo ed effetti restano legati all'ambito nel UnitFrame o GroupFrame corrispondente."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "Lo Stile individuale si modifica qui. Tema icone condiviso: Aspetto > Stile dell'Aura."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "Disposizione, filtri, elenchi e ogni Stile specifico del contenitore risiedono in ciascun riquadro. Aspetto > Stile dell'Aura gestisce solo il tema globale delle icone."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "Misurato dal centro del riquadro in anteprima. I valori positivi spostano verso destra. I tasti freccia e il trascinamento aggiornano la stessa posizione."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "Misurato dal centro del riquadro in anteprima. I valori positivi spostano verso l'alto. I tasti freccia e il trascinamento aggiornano la stessa posizione."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "Attivo (predefinito): i riquadri MSUF compaiono nella Modalità sblocco EllesmereUI. Disattivalo per continuare a usare la Modalità modifica nativa di MSUF. Le posizioni del profilo MSUF restano il riferimento."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "Apri il riquadro ed espandi Aure. Buff e debuff hanno disposizione, filtri, liste nere e Stile propri; Personalizzata 1-3, Buff difensivi e DoT sul bersaglio mostrano i controlli adatti al loro contenuto."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "Apre il tema globale delle icone aura: bordo, ombra, colori, spaziatura delle corsie e incantamenti dell'arma nativi del giocatore. Lo Stile individuale di questo GroupFrame resta qui."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "AVVISO PRESTAZIONI (12.1): Blizzard può eseguire un OnUpdate a ogni riquadro su ciascun pulsante aura visibile finché l'aura ha una finestra di pandemia calcolata, non solo mentre l'avviso è mostrato. Attivalo solo se accetti questo costo potenzialmente elevato in combattimento."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Applica una tinta segnaposto ai GroupFrames attivi per valutare la sovrapposizione senza un vero debuff dissolvibile. Si disattiva da sola alla chiusura di questa pagina."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "Applica una tinta segnaposto al UnitFrame attivo per valutare la sovrapposizione senza un vero debuff dissolvibile. Si disattiva da sola alla chiusura di questa pagina."
L["Position is controlled by the colored aura handle in Preview."] = "La posizione si regola con la maniglia aura colorata nell'Anteprima."
L["Preview position"] = "Posizione dell'anteprima"
L["Runtime Preview"] = "Anteprima in tempo reale"
L["Runtime Preview: live GroupFrames"] = "Anteprima in tempo reale: GroupFrames attivi"
L["Runtime Preview: live UnitFrame"] = "Anteprima in tempo reale: UnitFrame attivo"
L["Runtime Preview: live UnitFrame (drag)"] = "Anteprima in tempo reale: UnitFrame attivo (trascina)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "Forma, bordo e ombra: Aspetto > Stile dell'Aura > Buff. Tutti i controlli qui restano legati all'ambito di gruppo."
L["Shared Aura Style"] = "Stile dell'Aura condiviso"
L["Shared Aura Style: Buffs"] = "Stile dell'Aura condiviso: buff"
L["Shared Aura Style: Debuffs"] = "Stile dell'Aura condiviso: debuff"
L["Shared Preview - "] = "Anteprima condivisa - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "Mostra simboli segnaposto sul UnitFrame attivo e ti permette di trascinarli in posizione senza un vero debuff. Si disattiva da sola alla chiusura di questa pagina."
L["Spell Icon Style"] = "Stile delle Icone incantesimi"
L["Spell Icon tooltip"] = "Descrizione delle Icone incantesimi"
L["Swipe Direction"] = "Direzione dello sweep"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "Questo interruttore compare solo mentre EllesmereUI è caricato. Disattivandolo, MSUF torna subito alla propria Modalità modifica."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "Usa - / + oppure Ctrl + rotellina del mouse per lo zoom."
L["Use EllesmereUI Unlock Mode for MSUF"] = "Usa la Modalità sblocco EllesmereUI per MSUF"
L["Use the colored Texture handle in Preview for exact placement."] = "Usa la maniglia texture colorata nell'Anteprima per un posizionamento preciso."
L["Zoom changes only this preview, not your Aura settings."] = "Lo zoom modifica solo questa anteprima, non le tue impostazioni delle aure."

-- Menu localization pass 2026-08-06 (part 2): dropdown values, tooltips and labels routed through Tr() that the coverage extractor could not see.
L["+ Value"] = "+ Valore"
