L["Add spell"] = "Aggiungi incantesimo"
L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Aggiunge i pulsanti degli incantamenti d'arma temporanei di Blizzard al contenitore dei buff del giocatore. È un'unica impostazione condivisa e usa il flusso di aure nativo, senza ticker o OnUpdate di MSUF."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "Aggiunge un ID esatto di aura dannosa assente dall'elenco curato. L'aura resta comunque limitata al tuo bersaglio attuale e alle aure di cui sei la fonte."
L["Adds one exact buff to this frame's blacklist."] = "Aggiunge un buff esatto alla lista nera di questo riquadro."
L["Adds one exact buff to this group's blacklist."] = "Aggiunge un buff esatto alla lista nera di questo gruppo."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "Aggiunge un'aura dannosa esatta alla lista nera di Bersaglio, Focus o Boss. Blizzard applica filtri SpellID arbitrari solo finché non puoi assistere l'unità."
L["All Buffs"] = "Tutti i buff"
L["All Debuffs"] = "Tutti i debuff"
L["All roles"] = "Tutti i ruoli"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "Esclude sempre le aure senza durata, anche quando i filtri token di Blizzard sono disattivati."
L["Always excludes auras without a duration."] = "Esclude sempre le aure senza durata."
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "Esclude sempre le aure senza durata. Resta attivo quando i filtri token sono disattivati."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "Esclude sempre le aure senza durata. Questa regola nativa prevale su liste nere e liste bianche di SpellID."
