L["Any Dispel Type"] = "Qualsiasi tipo di dissolvimento"
L["Any dispel type"] = "Qualsiasi tipo di dissolvimento"
L["Applicable by Me (Raid)"] = "Applicabile da me (incursione)"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "Si applica a ogni icona UnitFrame e GroupFrame di questo tipo di aura. Le Icone incantesimi usano l'aspetto dei buff."
L["Aura sort order"] = "Ordine delle aure"
