L["Auto: Unit Frame"] = "Automatico: riquadro unità"
L["Auto: Utility Cooldowns"] = "Automatico: recuperi ausiliari"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "Solo barra nasconde l'icona dell'aura. Icona + barra mantiene l'icona e vi disegna sopra la barra della durata."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "Barra mantiene la normale barra di stato. Segui risorsa giocatore rispecchia la forma della risorsa del giocatore staccata. Sfera usa un unico riempimento verticale."
L["Big Defensive"] = "Grande difensiva"
L["Big Defensive Player"] = "Grande difensiva (giocatore)"
L["Blizzard castbar"] = "Barra di lancio Blizzard"
L["Blizzard ring + symbol"] = "Anello + simbolo Blizzard"
L["Blizzard symbol"] = "Simbolo Blizzard"
L["Blocks every aura in the selected curated MSUF set."] = "Blocca ogni aura del set curato di MSUF selezionato."
L["Blocks only the selected aura from the curated set."] = "Blocca solo l'aura selezionata dal set curato."
L["Cancelable Player"] = "Annullabile (giocatore)"
L["Castbar Border"] = "Bordo della barra di lancio"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "Modifica solo la barra della risorsa del giocatore staccata. La forma della risorsa di classe a sinistra modifica solo le risorse di classe."
L["Class Resource Preview"] = "Anteprima della risorsa di classe"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "La risorsa di classe e la risorsa del giocatore seguono i riquadri esistenti. Personalizzato usa il cursore qui sotto. La larghezza viene risolta solo durante l'aggiornamento della disposizione."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "Controlla solo il contorno della seconda barra della salute. Barra usa i quattro bordi esterni; le forme usano la loro texture di bordo fissa. 0 disattiva soltanto il contorno."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "Controlla solo questa seconda barra della salute. Il normale testo della salute del riquadro giocatore resta separato."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "Controlla questa corsia di aure in modo indipendente. Sempre / Fuori combattimento / Modificatore / Mai, in Stile globale > Varie, riguardano solo i riquadri unità e gruppo. Le aure riutilizzano soltanto l'aspetto Blizzard/MSUF scelto e la posizione del cursore."
L["Cooldown swipe direction"] = "Direzione dello sweep di recupero"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "Funzione principale attiva per impostazione predefinita nei nuovi profili e una sola volta in quelli esistenti. Funziona come una normale barra di buff difensivi anche senza ritratto attivo. Disattivala per rimuovere sia la barra sia la presentazione nella posizione del ritratto."
L["Crowd Control"] = "Controllo della folla"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Aure DoT curate per Retail 12.0+ e 12.1. Il monitoraggio è limitato all'unità di questo UnitFrame e alle aure di cui sei la fonte; le impostazioni Boss si legano separatamente da boss1 a boss5."
L["Custom Spell ID"] = "ID incantesimo personalizzato"
L["Dark Border"] = "Bordo scuro"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "Disattivato per impostazione predefinita. L'implementazione nativa di Blizzard abilita un OnUpdate per riquadro su ogni pulsante aura visibile non appena quell'aura ha una finestra di pandemia calcolata; ciò può iniziare prima che l'avviso diventi visibile."
L["Dispellable by Group"] = "Dissolvibile dal gruppo"
