L["Duration bar position"] = "Posizione della barra della durata"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "Intensità del bordo di ogni forma della risorsa del giocatore staccata, incluse Barra, Rotonda, Cristallo e Sfera. 0 disattiva soltanto quel bordo."
L["Elapsed / Total"] = "Trascorso / totale"
L["Enable defensive buffs"] = "Attiva i buff difensivi"
L["Enable tracked DoTs"] = "Attiva i DoT monitorati"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "Inserisci un ID incantesimo, incolla un collegamento a un incantesimo o digita un nome. L'aura benefica visibile viene riconosciuta anche se il suo ID buff differisce dall'ID dell'incantesimo lanciato."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "Inserisci un ID incantesimo, incolla un collegamento a un incantesimo o digita un nome. Questa lista bianca monitora ID incantesimo esatti."
L["Essential cooldown viewer"] = "Visualizzatore dei recuperi essenziali"
L["Exact aura tracking"] = "Monitoraggio esatto delle aure"
L["External Defensive"] = "Difensiva esterna"
L["External Defensive Player"] = "Difensiva esterna (giocatore)"
L["Fill Mode"] = "Modalità di riempimento"
L["Focus off"] = "Focus disattivato"
L["Focus on"] = "Focus attivato"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global segue la normale modalità colore salute di MSUF. Class Color impone il colore della tua classe. Dark Mode impone il colore barra scuro configurato. HP Gradient colora solo questa seconda barra della salute in base alla salute attuale."
L["Global icon shape"] = "Forma globale dell'icona"
L["HP Color"] = "Colore della salute"
L["HP Outline"] = "Contorno della salute"
L["HP Shape"] = "Forma della barra della salute"
L["HP only"] = "Solo salute"
L["Healers only"] = "Solo guaritori"
L["Hide permanent auras"] = "Nascondi le aure permanenti"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "Nasconde gli ID incantesimo dei DoT selezionati in questo ambito dal normale contenitore dei debuff dello stesso UnitFrame mentre DoT sul bersaglio è attivo. La lista nera di Blizzard funziona per SpellID, quindi lo stesso incantesimo lanciato da un altro giocatore viene nascosto anche lì."
L["Highest priority only"] = "Solo la priorità più alta"
L["Icon Border & Shadow"] = "Bordo e ombra dell'icona"
L["Include Nameplate-only"] = "Includi solo barre del nome"
L["Inside Left"] = "Interno sinistra"
L["Inside Right"] = "Interno destra"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "Mantiene la risorsa del giocatore staccata agganciata alla barra della risorsa di classe. I controlli della risorsa del giocatore restano disattivati finché questo collegamento è attivo."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "Mantiene dimensione e posizione configurate del ritratto come ancoraggio invisibile, così l'icona difensiva può restare lì mentre il ritratto stesso è disattivato."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "Mantiene dimensione, posizione e forma configurate del ritratto come ancoraggio invisibile per i DoT monitorati mentre il ritratto stesso è disattivato."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "Limita le icone DoT simultanee sul ritratto da 1 a 8. Le icone aggiuntive crescono verso l'esterno seguendo la direzione di crescita configurata per questa corsia DoT."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "Limita il numero di icone difensive simultanee sul ritratto da 1 a 8. I profili esistenti restano a 1 finché non modifichi questo valore."
L["Lists every MSUF slash command in chat, diagnostics included."] = "Elenca in chat tutti i comandi slash di MSUF, diagnostica inclusa."
L["Max portrait icons"] = "Max icone sul ritratto"
L["Maximum debuff duration"] = "Durata massima del debuff"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "Sposta insieme tutti gli slot di testo della risorsa del giocatore staccata. I controlli X/Y degli slot qui sotto aggiungono scostamenti individuali."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "Sposta la barra della risorsa del giocatore fuori dal riquadro unità. Aggancia la collega alla pila delle risorse di classe; Sincronizza ne segue soltanto la larghezza."
L["Native Aura Flow"] = "Flusso di aure nativo"
L["Blizzard Buff & Debuff Frames"] = "Riquadri benefici e penalità di Blizzard"
L["Hide Blizzard Buff and Debuff Frames"] = "Nascondi i riquadri benefici e penalità di Blizzard"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Nasconde solo il riquadro benefici del giocatore di Blizzard e le normali icone delle penalità vicino alla minimappa. Le aure private e gli avvisi di penalità letali restano visibili."
L["Buffs hidden"] = "Benefici nascosti"
L["Buffs visible"] = "Benefici visibili"
L["Debuffs hidden"] = "Penalità nascoste"
L["Debuffs visible"] = "Penalità visibili"
L["Hide Blizzard Buff Frame"] = "Nascondi il riquadro benefici di Blizzard"
L["Hide Blizzard Debuff Frame"] = "Nascondi il riquadro penalità di Blizzard"
L["Hides Blizzard's player Buff Frame near the minimap."] = "Nasconde il riquadro benefici del giocatore di Blizzard vicino alla minimappa."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "Nasconde solo le normali icone delle penalità di Blizzard vicino alla minimappa. Le aure private e gli avvisi di penalità letali restano visibili."
L["Native size"] = "Dimensione nativa"
L["Native stealable marker"] = "Marcatore nativo di rubabilità"
L["Native weapon enchant auras"] = "Aure native di incantamento dell'arma"
L["No roles"] = "Nessun ruolo"
L["No width limit"] = "Nessun limite di larghezza"
L["Not Cancelable"] = "Non annullabile"
L["Not Cancelable Player"] = "Non annullabile (giocatore)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "Disattivato mostra i debuff di qualsiasi durata. Altrimenti vengono nascosti i debuff la cui durata totale supera questo numero di secondi."
L["One per dispel type"] = "Uno per tipo di dissolvimento"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "Apre il tema globale delle icone aura: bordo, ombra, colori, spaziatura delle corsie e incantamenti dell'arma nativi del giocatore. Lo Stile del contenitore di questo riquadro resta qui."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "Interpolazione opzionale per questa seconda barra della salute. Disattivata mantiene gli aggiornamenti nativi diretti di SetValue."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "Modalità di presentazione opzionale; la funzione Buff difensivi non richiede un ritratto. Con il ritratto attivo, la prima icona lo occupa. Con il ritratto disattivato, attiva l'opzione di posizione qui sotto per mantenervi le icone; altrimenti MSUF torna in sicurezza alla normale barra difensiva."
L["Orb Size"] = "Dimensione della sfera"
L["Pandemic Warning & Style"] = "Avviso pandemia e stile"
L["Pandemic color"] = "Colore pandemia"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "Colloca il testo della risorsa del giocatore sulla barra della risorsa staccata. Se disattivato, lo stesso testo resta posizionato dalla normale disposizione del testo."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "Colloca la barra della durata sul bordo superiore o inferiore dello slot dell'aura."
L["Player Text Outline"] = "Contorno del testo del giocatore"
L["Power Bar Outline"] = "Contorno della barra della risorsa"
L["Power Text On Bar"] = "Testo della risorsa sulla barra"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "Gli ancoraggi della risorsa usano la barra della risorsa del giocatore quando è visibile; altrimenti la barra della salute ricade sull'ancoraggio della risorsa di classe."
L["Raid In Combat"] = "Incursione in combattimento"
L["Raid In Combat Player"] = "Incursione in combattimento (giocatore)"
L["Raid Player"] = "Incursione (giocatore)"
L["Remaining / Total"] = "Rimanente / totale"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "Rimanente si riduce mentre l'aura scade. Trascorso cresce fino alla scadenza dell'aura."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "Al di sotto di questo valore il tempo rimanente usa un decimale. I timer mostrano secondi senza unità sotto 1 minuto e minuti localizzati oltre tale soglia. Imposta 0 per usare solo secondi interi."
L["Remove from blacklist"] = "Rimuovi dalla lista nera"
L["Remove from whitelist"] = "Rimuovi dalla lista bianca"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "Disegna una seconda barra della salute nativa del giocatore. La normale barra della salute del riquadro giocatore resta intatta, così puoi mostrare la salute due volte."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "Sostituisce la normale corsia DoT con icone della dimensione del ritratto. La prima icona segue esattamente larghezza, altezza e forma del ritratto di questo riquadro."
L["Runs /msuf reset for frame positions and visibility."] = "Esegue /msuf reset per posizioni e visibilità dei riquadri."
L["Second Player HP Bar"] = "Seconda barra della salute del giocatore"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "Imposta l'ambito del carattere del giocatore usato dal testo della risorsa staccata. Nome del giocatore e testo della salute condividono questa impostazione di contorno."
L["Show DoTs at portrait position"] = "Mostra i DoT nella posizione del ritratto"
L["Show buffs at portrait position"] = "Mostra i buff nella posizione del ritratto"
L["Show cooldown text on portrait"] = "Mostra il testo di recupero sul ritratto"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "Mostra la durata rimanente del buff difensivo attivo sopra la sua icona nel ritratto. Blizzard aggiorna il testo in modo nativo."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "Mostra qui sotto la risorsa della classe o specializzazione selezionata senza modificare il personaggio, la specializzazione o le impostazioni salvate."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "Mostra la durata rimanente del DoT monitorato sopra la sua icona nel ritratto. Blizzard aggiorna la durata in modo nativo."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "Preimpostazioni semplici per il testo della risorsa del giocatore mentre la risorsa staccata è gestita dalle risorse di classe. Slot personalizzati mantiene la disposizione degli slot attuale finché non scegli una preimpostazione."
L["Smooth Fill"] = "Riempimento fluido"
L["Spell Text"] = "Testo dell'incantesimo"
L["Stops blocking this aura."] = "Smette di bloccare questa aura."
L["Sync Width"] = "Sincronizza larghezza"
L["Tanks only"] = "Solo difensori"
L["Target DoT"] = "DoT sul bersaglio"
L["Target off"] = "Bersaglio disattivato"
L["Target on"] = "Bersaglio attivato"
L["Time Text"] = "Testo del tempo"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "Monitora questo buff difensivo predefinito. L'impostazione vale sia per la barra difensiva sia per l'icona opzionale nel ritratto."
L["Tracked buffs viewer"] = "Visualizzatore dei buff monitorati"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "Monitora le aure dannose che selezioni sull'unità di questo UnitFrame. I riquadri boss usano i propri token unità, da boss1 a boss5."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "Attiva o disattiva i filtri token di Blizzard per questo riquadro. La prima modifica crea automaticamente regole specifiche del riquadro; le regole condivise migrate restano condivise finché non vengono modificate."
L["Unavailable cast fill"] = "Riempimento per lancio non disponibile"
L["Up (Single Column)"] = "Verso l'alto (colonna singola)"
L["Use Player HP Text"] = "Usa il testo della salute del giocatore"
L["Use portrait position while portrait is off"] = "Usa la posizione del ritratto con il ritratto disattivato"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "Usato solo quando questa barra della salute è impostata esplicitamente su Sfera. Segui risorsa giocatore eredita invece la dimensione della sfera della risorsa del giocatore."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Usa il filtro di rubabilità AuraButton di Blizzard 12.1. Non aggiunge alcuna scansione delle aure, ticker o OnUpdate di MSUF."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "Usa le impostazioni del testo della salute del giocatore e copia il testo già disegnato quando è aggiornato. I valori locali di testo X/Y restano di questa barra."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "Usa la larghezza della risorsa di classe per la risorsa del giocatore staccata senza che le risorse di classe si approprino dei suoi controlli."
L["Utility cooldown viewer"] = "Visualizzatore dei recuperi ausiliari"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "Visibile dietro la porzione di salute riempita. Al 100% di salute il riempimento copre lo sfondo; un contorno pari a 0 non disattiva questa texture."
L["Weapon Enchants Off"] = "Incantamenti d'arma disattivati"
L["Weapon Enchants On"] = "Incantamenti d'arma attivati"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "Finché la barra difensiva o l'icona nel ritratto è attiva, nasconde dalla normale corsia dei buff del giocatore ogni difensiva monitorata attiva. Le voci difensive disattivate restano visibili lì."
L["Whole frame"] = "Riquadro intero"
L["Width Mode"] = "Modalità larghezza"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "Tinta di sfondo della barra Colore personalizzato in modalità scura sfondo bg opacità alfa background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "Base del riquadro Attiva Condizioni di caricamento Opacità Dissolvenza per distanza giocatore bersaglio focus famiglio assente invisibile"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "Base del riquadro Riempimento liscio Barra risorsa Riempimento liscio animazione salute animazione risorsa smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "Generale Usa i riquadri di gruppo MSUF Se questo interruttore è disattivato attiva disattiva nascondi incursione gruppo mitica"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "Frame gruppo/raid Disposizione Riempimento liscio della salute Testo salute Barra risorsa Riempimento liscio gruppo incursione smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "Frame gruppo/raid Disposizione Opacità trasparenza dissolvenza bersaglio in combattimento fuori combattimento alfa riquadro intero barre salute sfondo riempimento salute traccia salute mantieni colore salute"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "La Modalità modifica di MSUF sposta i riquadri e le barre di lancio supportate. La posizione delle icone aura si imposta dalla pagina di ciascuna unità > Aure oppure in Frame gruppo/raid > Aure."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "Varie stile globale lingua comportamento del menu avvisi di avvio descrizioni riquadri Blizzard minimappa suoni"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "Abbreviazione del nome Usa impostazioni personalizzate per questo ambito Sostituisce gruppo incursione abbreviazione dei nomi nei riquadri di gruppo sostituzione del carattere modifiche condivise"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "Apri Aspetto > Aure per il testo di recupero, il testo degli accumuli, lo sweep e lo stile della barra della durata legati all'ambito. I colori dei timer restano in Colori > Aure."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "Apri Riquadri boss > Aure > Debuff. Le voci di lista nera per SpellID, i filtri Blizzard, la posizione e l'anteprima si trovano lì insieme; lo stile resta in Aspetto > Aure."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "Apri Stile globale > Varie > Descrizioni dei riquadri unità per controllare origine, ancoraggio, modalità di visibilità e tasto modificatore delle descrizioni nei riquadri unità e gruppo di MSUF."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "Apri Stile globale > Varie per lingua, comportamento del menu, avvisi di avvio, descrizioni, riquadri Blizzard, icona della minimappa e suoni."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "Apri Frame gruppo/raid > Disposizione > Dissolvenza per distanza. Interessa sceglie la dissolvenza del riquadro o della salute e i cursori alfa controllano l'opacità fuori portata e offline."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "Apri Frame gruppo/raid > Disposizione > Opacità. Opacità controlla l'alfa in e fuori combattimento; Bersaglio della dissolvenza sceglie riquadro intero, barre, salute o sfondo. I livelli Sfondo e Salute impostano il colore base e l'opacità di riempimento e traccia della salute."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "Apri Frame gruppo/raid > Disposizione per il Riempimento liscio della salute. Per le barre risorsa dei riquadri di gruppo apri Frame gruppo/raid > Disposizione > Barra delle risorse > Riempimento liscio."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "Apri Frame gruppo/raid > Disposizione, scegli Gruppo, Incursione o Mitica in alto, poi disattiva Usa i riquadri di gruppo MSUF. Usa Se questo interruttore è disattivato per scegliere se i riquadri Blizzard compaiono normalmente o se entrambi i sistemi restano nascosti."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "Apri Frame gruppo/raid > Disposizione. Base del riquadro e Ordinamento controllano la visibilità del giocatore e di te stesso e l'ordine delle unità nei riquadri di gruppo."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "Apri Frame gruppo/raid > Disposizione. Base del riquadro/Disposizione controlla larghezza, altezza, spaziatura, colonne e crescita; Ridimensionamento del riquadro controlla il comportamento della scala."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "Apri Frame gruppo/raid > Stato e indicatori per icone di stato, ruolo/capo/assistente, controllo di preparazione, bagliore del focus e altri indicatori di stato dei riquadri di gruppo."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "Apri Giocatore > Aure, poi disattiva Buff per il riquadro del giocatore. Lo stile di testo e recupero legato all'ambito resta in Aspetto > Aure."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "Apri una pagina unità, poi usa Dissolvenza per distanza. È disponibile per Bersaglio, Bersaglio del bersaglio, Focus, Bersaglio del focus, Famiglio e Boss."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "Apri il UnitFrame interessato > Aure per dimensione dell'icona, posizione e filtri. Usa Aspetto > Aure per il testo e lo stile di recupero legati all'ambito."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "Apri il UnitFrame interessato > Aure oppure Frame gruppo/raid > Aure e riduci il numero di aure visibili, il testo dei timer o le regole di filtro native non necessarie."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "Apri il UnitFrame interessato > Aure, scegli Buff o Debuff, poi regola filtri, dimensione delle icone, righe, limiti e spaziatura. Le impostazioni per gruppo e incursione sono in Frame gruppo/raid > Aure."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "Apri la pagina unità > Aure oppure la finestra di posizione delle aure per collocare le aure del riquadro unità. Le icone di buff e debuff si configurano come disposizione delle aure e non si spostano con la Modalità modifica di MSUF."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "Dissolvenza per distanza riquadro di gruppo controllo portata incursione gruppo fuori portata alfa opacità offline interessa riquadro salute"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "Dissolvenza per distanza riquadro unità controllo portata controllo distanza fuori portata alfa di portata bersaglio bersaglio del bersaglio focus bersaglio del focus famiglio boss"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "Texture arrotondata Texture del riquadro arrotondata Riquadri unità Riquadri di gruppo Barre risorsa Evidenziazioni al passaggio del mouse riquadri arrotondati angoli arrotondati"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "Icone di stato Indicatore Livello Attivato Punto di aggancio Scostamento X Scostamento Y Dimensione Livello di disegno testo del livello indicatore del livello livello del giocatore livello del bersaglio"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "Testo punto di aggancio scostamento dimensione del carattere livello ordine di disegno spaziatura spaziatura divisa sovrapposizioni barre ritratti icone di stato"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "Usa Frame gruppo/raid > Disposizione per dimensione e spaziatura dei riquadri, Aure per la posizione di buff e debuff e Stato e indicatori per le icone di stato a posizione fissa."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "Usa le pagine Frame gruppo/raid: Disposizione per dimensione, crescita, ordinamento, barre e testo; Aure per la posizione di buff e debuff e Stato e indicatori per le icone di stato."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "Usa la pagina unità per gli interruttori della barra di lancio per singola unità e Stile globale > Barra di lancio per texture, direzione, testo e opzioni di interruzione condivisi."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "Benvenuto nelle Risorse di classe!\n\nVuoi configurare automaticamente una\nbarra di classe staccata posizionata sopra i tuoi\nrecuperi essenziali?\n\nQuesto imposta in un clic la visibilità della risorsa\ndi classe, l'ancoraggio, l'allineamento della larghezza\ne la risorsa del giocatore staccata.\n\nPuoi sempre rifarlo più tardi tramite il pulsante\n|cff00ff00Configurazione rapida: barra classe|r qui sotto."
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
L["Show Details! in MSUF Edit Mode"] = "Show Details! in MSUF Edit Mode"
L["Details! Edit Mode integration"] = "Details! Edit Mode integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."

