L["DandersFrames Edit Mode integration"] = "Integrazione di DandersFrames con la Modalità modifica"
L["On (default): MSUF Edit Mode can move the DandersFrames party and raid containers and free pinned sets. Sets glued to the frames follow them, and DandersFrames remains the owner of all saved positions."] = "Attivo (predefinito): la Modalità modifica di MSUF può spostare i contenitori di gruppo e incursione di DandersFrames e i set bloccati liberi. I set agganciati ai riquadri li seguono e DandersFrames resta il proprietario di tutte le posizioni salvate."

-- Menu localization pass 2026-08-07 (part 3): DandersFrames popup preview toggles.
L["Show party preview"] = "Mostra anteprima del gruppo"
L["Show raid preview"] = "Mostra anteprima dell'incursione"

-- Menu localization pass 2026-08-07 (part 4): Dominos popup layout controls.
L["Buttons"] = "Pulsanti"
L["Columns"] = "Colonne"
L["Padding"] = "Margine interno"
L["Faded opacity"] = "Opacità attenuata"
L["Click through"] = "Clic attraverso"

-- Menu localization pass 2026-08-07 (part 5): Blizzard Edit Mode integration.
L["Show Blizzard frames in MSUF Edit Mode"] = "Mostra i riquadri Blizzard nella Modalità modifica di MSUF"
L["Blizzard Edit Mode integration"] = "Integrazione con la Modalità modifica di Blizzard"
L["On (default): MSUF Edit Mode can move the Blizzard Minimap, Chat, Micro Menu and Tooltip through the game's own Edit Mode layout. If a Blizzard preset is active, selecting an element creates and activates a saved 'MSUF' layout automatically."] = "Attivo (predefinito): la Modalità modifica di MSUF può spostare minimappa, chat, micromenu e tooltip di Blizzard tramite la disposizione della Modalità modifica del gioco. Se è attiva una preimpostazione Blizzard, selezionare un elemento crea e attiva automaticamente una disposizione salvata 'MSUF'."

-- Menu localization pass 2026-08-08 (part 2): Blizzard Edit Mode profile opt-in.
L["Include Blizzard Edit Mode layout"] = "Includi disposizione della Modalità modifica Blizzard"
L["Off (default): profile strings never carry or change the Blizzard Edit Mode arrangement. On: full-profile exports include it and imports apply it."] = "Disattivato (predefinito): le stringhe profilo non contengono né modificano mai la disposizione della Modalità modifica Blizzard. Attivato: le esportazioni del profilo completo la includono e le importazioni la applicano."

-- Menu localization pass 2026-08-08 (part 3): Blizzard layout dialog status line.
L["All Edit Mode layout slots are full (5 account + 5 character). Delete a layout in Blizzard's Edit Mode, then try again."] = "Tutti gli spazi per le disposizioni della Modalità modifica sono occupati (5 account + 5 personaggio). Elimina una disposizione nella Modalità modifica di Blizzard e riprova."
L["Layout creation failed:"] = "Creazione della disposizione non riuscita:"

-- Menu localization pass 2026-08-08: Blizzard layout dialog.
L["Create Edit Mode layout"] = "Crea disposizione della Modalità modifica"
L["Blizzard presets cannot be edited. Save a copy as a new layout to move and adjust Blizzard frames."] = "Le preimpostazioni Blizzard non possono essere modificate. Salva una copia come nuova disposizione per spostare e regolare i riquadri Blizzard."
L["Create"] = "Crea"

-- Menu localization pass 2026-08-06 (part 6): pandemic badge format key.
L["On / %s"] = "Attivo / %s"

-- Menu localization pass 2026-08-06 (part 7): entries that were still identity English.
L["Confirm anchoring"] = "Conferma ancoraggio"
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Conferma solo se vuoi che l'intera disposizione del riquadro unità si sposti insieme ai tuoi recuperi."
L["Keep independent"] = "Mantieni indipendente"
L["MSUF detected %s."] = "MSUF ha rilevato %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF ancorerà ora la disposizione globale del riquadro unità a Essential Cooldown Manager."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Non si sposterà nulla finché non confermi di nuovo al passaggio successivo. Se scegli Mantieni indipendente, puoi attivare l'ancoraggio CDM in qualsiasi momento nella Modalità modifica di MSUF oppure in Unità > Ancoraggio nel menu di MSUF."
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Non si sposterà nulla finché non confermi di nuovo al passaggio successivo. Puoi cambiarlo più tardi nella Modalità modifica di MSUF."
L["Second confirmation for %s."] = "Seconda conferma per %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Vuoi che MSUF ancori la disposizione globale del riquadro unità a Essential Cooldown Manager?"
L["Dashboard"] = "Pannello"
L["Deficit"] = "Deficit di salute"
L["Slot X"] = "Slot X"
L["Slot Y"] = "Slot Y"
L["Unitframes"] = "Riquadri unità"
-- Menu localization pass 2026-08-06 (part 7): native Player resource pings.
L["Enable native Player resource pings (12.1)"] = "Abilita i ping nativi delle risorse del giocatore (12.1)"
L["Native Player resource pings"] = "Ping nativi delle risorse del giocatore"
L["Contextual pings over the MSUF Player frame can call out health and, when Blizzard supports it, mana. Blizzard does not expose separate Health/Power selection or Energy, Rage and Focus pings. The portrait keeps the normal Player unit ping and radial wheel."] = "I ping contestuali sul riquadro Giocatore di MSUF possono segnalare salute e, quando supportato da Blizzard, mana. Blizzard non espone una selezione separata Salute/Risorsa né ping per Energia, Rabbia o Concentrazione. Sul ritratto restano disponibili il normale ping unità del giocatore e il menu radiale."
L["Edits the selected element's X position. Positive values move right. Arrow keys and dragging update the same position."] = "Modifica la posizione X dell'elemento selezionato. I valori positivi lo spostano a destra. Le frecce e il trascinamento aggiornano la stessa posizione."
L["Edits the selected element's Y position. Positive values move up. Arrow keys and dragging update the same position."] = "Modifica la posizione Y dell'elemento selezionato. I valori positivi lo spostano verso l'alto. Le frecce e il trascinamento aggiornano la stessa posizione."
L["Exact X position"] = "Posizione X esatta"
L["Exact Y position"] = "Posizione Y esatta"
L["External frame"] = "Riquadro esterno"
L["Next page"] = "Pagina successiva"
L["Previous page"] = "Pagina precedente"

L["UnitFrame Debuff blacklist"] = "Lista di blocco dei debuff delle UnitFrame"
L["You can blacklist any debuff applied by the player on the %s UnitFrame using its exact Spell ID."] = "Puoi inserire nella lista di blocco qualsiasi debuff applicato dal giocatore sulla UnitFrame %s usando il suo ID incantesimo esatto."

-- Completamento della localizzazione completa derivata da Menu2.
L["Aura settings are only available for Player, Target, Focus, and Boss Frames."] = "Le impostazioni delle aure sono disponibili solo per i riquadri Giocatore, Bersaglio, Focus e Boss."
L["Aura settings were skipped for unsupported UnitFrames."] = "Le impostazioni delle aure sono state ignorate per i riquadri unità non supportati."
L["Blizzard animated Zzz"] = "Zzz animate di Blizzard"
L["Bottom half"] = "Metà inferiore"
L["Castbar settings are only available for Player, Target, Focus, and Boss Frames."] = "Le impostazioni della barra di lancio sono disponibili solo per i riquadri Giocatore, Bersaglio, Focus e Boss."
L["Castbar settings were skipped for UnitFrames without Castbars."] = "Le impostazioni della barra di lancio sono state ignorate per i riquadri unità senza barra di lancio."
L["Changing this value selects Manual width. For Player, it also turns off Sync width to Class Resource so the new width takes effect immediately."] = "La modifica di questo valore seleziona Larghezza manuale. Per il Giocatore disattiva anche Sincronizza la larghezza con la risorsa della classe, così la nuova larghezza viene applicata immediatamente."
L["Current target only"] = "Solo bersaglio attuale"
L["Edits the selected child element's local X offset. Positive values move right. Arrow keys and dragging update the same offset."] = "Modifica l'offset X locale dell'elemento figlio selezionato. I valori positivi lo spostano a destra. I tasti freccia e il trascinamento aggiornano lo stesso offset."
L["Edits the selected child element's local Y offset. Positive values move up. Arrow keys and dragging update the same offset."] = "Modifica l'offset Y locale dell'elemento figlio selezionato. I valori positivi lo spostano verso l'alto. I tasti freccia e il trascinamento aggiornano lo stesso offset."
L["Exact X offset"] = "Offset X esatto"
L["Exact Y offset"] = "Offset Y esatto"
L["Full texture"] = "Texture completa"
L["Height (0 = auto)"] = "Altezza (0 = automatica)"
L["Highlight texture"] = "Texture di evidenziazione"
L["No copy categories selected."] = "Nessuna categoria di copia selezionata."
L["Nothing was copied."] = "Non è stato copiato nulla."
L["Outline style"] = "Stile del contorno"
L["Rounded frames ignore True Outline and Texture styles and keep the solid outline color."] = "I riquadri arrotondati ignorano gli stili Contorno reale e Texture e mantengono il colore uniforme del contorno."
L["Texture region"] = "Regione della texture"
L["Top half"] = "Metà superiore"
